package com.bank.observ;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;

// The METRICS pillar: cheap numeric time-series. Low-cardinality labels only.
public class MetricsRegistry {
    private final AtomicLong transfersTotal = new AtomicLong();
    private final AtomicLong transfersFailed = new AtomicLong();
    private final List<Long> latenciesMs = new ArrayList<>();   // for percentiles

    public void recordTransfer(boolean success, long latencyMs) {
        transfersTotal.incrementAndGet();
        if (!success) transfersFailed.incrementAndGet();
        synchronized (latenciesMs) { latenciesMs.add(latencyMs); }
    }

    public double errorRate() {
        long total = transfersTotal.get();
        return total == 0 ? 0.0 : (double) transfersFailed.get() / total;
    }

    // p95 latency — the number metrics are famous for.
    public long p95LatencyMs() {
        synchronized (latenciesMs) {
            if (latenciesMs.isEmpty()) return 0;
            List<Long> sorted = new ArrayList<>(latenciesMs);
            sorted.sort(Long::compareTo);
            int idx = (int) Math.ceil(0.95 * sorted.size()) - 1;
            return sorted.get(Math.max(0, idx));
        }
    }

    public String snapshot() {
        return String.format("transfers_total=%d failed=%d error_rate=%.2f%% p95_latency=%dms",
            transfersTotal.get(), transfersFailed.get(), errorRate() * 100, p95LatencyMs());
    }
}
