package com.bank.observ;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

// The TRACES pillar: one trace id, many spans, showing where time went.
public class Tracer {
    private final String traceId = UUID.randomUUID().toString().substring(0, 8);
    private final List<Span> spans = new ArrayList<>();

    public String getTraceId() { return traceId; }

    public void addSpan(String name, long durationMs, boolean error) {
        spans.add(new Span(name, durationMs, error));
    }

    public List<Span> getSpans() { return spans; }

    // Render the waterfall so the engineer sees the slow hop.
    public String waterfall() {
        StringBuilder sb = new StringBuilder("trace " + traceId + ":\n");
        for (Span s : spans) {
            sb.append(String.format("    %-16s %5dms %s%n",
                s.getName(), s.getDurationMs(), s.isError() ? "ERROR" : "ok"));
        }
        return sb.toString();
    }
}
