package com.bank.observ;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Emits all THREE pillars while processing one transfer.
public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    private final MetricsRegistry metrics;

    public TransferService(MetricsRegistry metrics) {
        this.metrics = metrics;
    }

    public void transfer(String fromId, String toId, BigDecimal amount, Tracer tracer) {
        long start = System.currentTimeMillis();
        String traceId = tracer.getTraceId();

        // LOGS pillar: each log line carries the traceId for correlation.
        log.info(() -> "[trace=" + traceId + "] validating transfer " + amount
                + " from " + fromId + " to " + toId);
        tracer.addSpan("validate", 3, false);

        // Simulate a slow fraud-check hop that retried downstream.
        log.warning(() -> "[trace=" + traceId + "] fraud-check slow: retried downstream 3x");
        tracer.addSpan("fraud-check", 4200, false);   // the slow span

        log.fine(() -> "[trace=" + traceId + "] debit " + fromId + " by " + amount);
        tracer.addSpan("debit", 5, false);

        log.fine(() -> "[trace=" + traceId + "] credit " + toId + " by " + amount);
        tracer.addSpan("credit", 5, false);

        tracer.addSpan("notify", 12, false);
        long latency = System.currentTimeMillis() - start + 4225;   // include simulated hop time
        metrics.recordTransfer(true, latency);

        log.info(() -> "[trace=" + traceId + "] transfer COMPLETED in " + latency + "ms");
    }
}
