package com.bank.observ;

import java.math.BigDecimal;
import java.util.logging.*;

// Runnable demo: one transfer emits metrics, a trace, and correlated logs.
public class ObservabilityDemo {
    private static final Logger log = Logger.getLogger(ObservabilityDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — observability demo for a slow transfer");

        MetricsRegistry metrics = new MetricsRegistry();
        TransferService service = new TransferService(metrics);
        Tracer tracer = new Tracer();

        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"), tracer);

        // METRICS: the dashboard pulse
        log.info("METRICS snapshot: " + metrics.snapshot());
        // TRACES: the waterfall shows WHERE the time went
        log.info("TRACE waterfall:\n" + tracer.waterfall());
        log.info("Diagnosis: metrics showed high p95, trace pinpointed fraud-check, "
               + "logs explained the 3 downstream retries.");
    }
}
